<script setup lang="ts">const {theme}=useTheme();const {load,schoolId,platformAdmin}=useSchool();const open=ref(false);const error=ref('');const loading=ref(true);onMounted(async()=>{try{if(!await load()) {await navigateTo('/login');return}if(!platformAdmin.value&&!schoolId.value)await navigateTo('/student')}catch(e:any){error.value=e?.message||'Unable to load workspace'}finally{loading.value=false}})</script><template><div class="sst" :data-theme="theme"><div v-if="open" class="fixed inset-0 z-30 bg-black/50 lg:hidden" @click="open=false"/><div class="flex min-h-screen"><LayoutSidebar :open="open" @close="open=false"/><div class="min-w-0 flex-1"><LayoutTopbar @menu="open=true"/><main class="mx-auto max-w-[1600px] px-4 py-7 md:px-8"><p v-if="loading">Loading workspace…</p><UiPanel v-else-if="error" role="alert">{{error}}</UiPanel><slot v-else/></main></div></div></div></template>